Lemma fz_ssh : forall (fx : FPState) regs (m : word -> option byte) (s : Z) (ret : word),
  store_ok SEGS m (Z_to_bv 64 234728) 8 = true ->
  getr regs 2 = Z_to_bv 64 s ->
  getr regs 10 = Z_to_bv 64 97184 ->
  getr regs 1 = ret ->
  ret_ok ret ->
  reach SEGS (@mkst fx regs (Z_to_bv 64 97472) m rom)
    (fun fin => exists regs' M', fin = @mkst fx regs' ret M' rom /\
      rinv [(234728%Z, 8%Z)] m M' /\ rdn SEGS M' (Z_to_bv 64 234728) 8 = Some (Z_to_le_bytes 8 97184) /\
