  getr regs 9 = Z_to_bv 64 dp ->
  reach SEGS (@mkst fx regs (Z_to_bv 64 97000) m rom)
    (fun fin => exists regs' M', fin = @mkst fx regs' (Z_to_bv 64 179032) M' rom /\
      M' = m /\ getr regs' 1 = Z_to_bv 64 97012 /\ getr regs' 2 = Z_to_bv 64 (s - 64) /\ getr regs' 10 = Z_to_bv 64 dp /\ getr regs' 11 = Z_to_bv 64 sz /\
      getr regs' 8 = Z_to_bv 64 sz /\ getr regs' 9 = Z_to_bv 64 dp /\ regs_agree (fun r => In r [1; 10; 11]%list) regs regs').
