Lemma fz_C : forall (fr : bvmap 5 word) cs regs (m : word -> option byte) (s c : Z),
  frm_zero cs ->
  (4096 + 64 <= s <= 2 ^ 47)%Z ->
  (0 <= c < 2 ^ 64)%Z ->
  store_ok SEGS m (Z_to_bv 64 (s - 64)) 64 = true ->
  getr regs 2 = Z_to_bv 64 (s - 64) ->
