Lemma fz_J : forall (fx : FPState) regs (m : word -> option byte) (s : Z),
  (4096 + 64 <= s <= 2 ^ 47)%Z ->
  getr regs 2 = Z_to_bv 64 (s - 64) ->
  reach SEGS (@mkst fx regs (Z_to_bv 64 97148) m rom)
    (fun fin => exists regs' M', fin = @mkst fx regs' (Z_to_bv 64 103464) M' rom /\
      M' = m /\ getr regs' 1 = Z_to_bv 64 97156 /\ getr regs' 2 = Z_to_bv 64 (s - 64) /\ getr regs' 10 = Z_to_bv 64 (s - 40) /\
      regs_agree (fun r => In r [1; 10]%list) regs regs').
Proof.
