Lemma fz_F : forall (fx : FPState) regs (m : word -> option byte) (s pixs : Z),
  (4096 + 64 <= s <= 2 ^ 47)%Z ->
  (0 <= pixs < 2 ^ 64)%Z ->
  getr regs 2 = Z_to_bv 64 (s - 64) ->
  getr regs 8 = Z_to_bv 64 pixs ->
  reach SEGS (@mkst fx regs (Z_to_bv 64 97092) m rom)
    (fun fin => exists regs' M', fin = @mkst fx regs' (Z_to_bv 64 105628) M' rom /\
      M' = m /\ getr regs' 1 = Z_to_bv 64 97104 /\ getr regs' 2 = Z_to_bv 64 (s - 64) /\ getr regs' 10 = Z_to_bv 64 0 /\ getr regs' 11 = Z_to_bv 64 pixs /\ getr regs' 8 = Z_to_bv 64 pixs /\
      regs_agree (fun r => In r [1; 10; 11]%list) regs regs').
Proof.
