Lemma fz_G : forall (fr : bvmap 5 word) cs regs (m : word -> option byte) (s pixs c : Z),
  frm_zero cs ->
  (4096 + 64 <= s <= 2 ^ 47)%Z ->
  (0 <= pixs < 2 ^ 64)%Z ->
  (0 <= c < 2 ^ 64)%Z ->
  store_ok SEGS m (Z_to_bv 64 (s - 64)) 64 = true ->
  getr regs 2 = Z_to_bv 64 (s - 64) ->
  getr regs 10 = Z_to_bv 64 c ->
  getr regs 8 = Z_to_bv 64 pixs ->
  reg_get fr 8 = Z_to_bv 64 18446744070507200512 ->
  reach SEGS (@mkst (mkFP fr cs) regs (Z_to_bv 64 97104) m rom)
    (fun fin => exists fr' cs' regs' M', fin = @mkst (mkFP fr' cs') regs' (Z_to_bv 64 190948) M' rom /\ frm_zero cs' /\
      rinv [((s - 56)%Z, 8%Z)] m M' /\ rdn SEGS M' (Z_to_bv 64 (s - 56)) 8 = Some (Z_to_le_bytes 8 c) /\
      getr regs' 1 = Z_to_bv 64 97128 /\ getr regs' 2 = Z_to_bv 64 (s - 64) /\ getr regs' 10 = Z_to_bv 64 pixs /\ getr regs' 8 = Z_to_bv 64 pixs /\
      regs_agree (fun r => In r [1; 10]%list) regs regs' /\
      reg_get fr' 10 = Z_to_bv 64 18446744070507200512 /\ reg_get fr' 11 = Z_to_bv 64 18446744070479937536 /\
      (forall r : reg, ~ In (ridx r) [10; 11]%nat -> reg_get fr' r = reg_get fr r)).
Proof.
