Lemma fz_Z : forall (fr : bvmap 5 word) cs regs (m : word -> option byte) (s : Z) (ret : word) (v1 v8 v9 g8 : word),
  frm_zero cs ->
  (4096 + 64 <= s <= 2 ^ 47)%Z ->
  ret_ok ret ->
  v1 = ret ->
  rdn SEGS m (Z_to_bv 64 (s - 8)) 8 = Some (word_to_le_bytes 8 v1) ->
  rdn SEGS m (Z_to_bv 64 (s - 16)) 8 = Some (word_to_le_bytes 8 v8) ->
  rdn SEGS m (Z_to_bv 64 (s - 24)) 8 = Some (word_to_le_bytes 8 v9) ->
  rdn SEGS m (Z_to_bv 64 (s - 32)) 8 = Some (word_to_le_bytes 8 g8) ->
  getr regs 2 = Z_to_bv 64 (s - 64) ->
  reach SEGS (@mkst (mkFP fr cs) regs (Z_to_bv 64 97156) m rom)
    (fun fin => exists fr' cs' regs' M', fin = @mkst (mkFP fr' cs') regs' ret M' rom /\ frm_zero cs' /\
      M' = m /\ getr regs' 2 = Z_to_bv 64 s /\ getr regs' 10 = Z_to_bv 64 0 /\ getr regs' 8 = v8 /\ getr regs' 9 = v9 /\
      regs_agree (fun r => In r [1; 2; 8; 9; 10]%list) regs regs' /\
      reg_get fr' 8 = g8 /\ (forall r : reg, ~ In (ridx r) [8]%nat -> reg_get fr' r = reg_get fr r)).
